arguments.new_str:
using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZipFile now always sets the EFS (UTF-8) flag
        // for non-ASCII entry names. Legacy Java consumer expects Shift-JIS,
        // so specify the encoding explicitly.
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create,
            Encoding.GetEncoding("shift_jis"));
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9 breaking change: [FromKeyedServices] now validates at startup
// that the service was registered as keyed; non-keyed fallback removed.
services.AddKeyedSingleton<ICache, RedisCache>("cache");

